import React, { useState, useRef, useEffect } from 'react';

function IntroOverlay({ onComplete }) {
  const [started, setStarted] = useState(false);
  const [showMessage, setShowMessage] = useState(false);
  const [fadeOut, setFadeOut] = useState(false);
  const audioRefs = useRef({
    sound1: null,
    sound2: null
  });

  useEffect(() => {
    // Initialize audio elements with absolute paths
    const baseUrl = window.location.origin + (process.env.PUBLIC_URL || '');
    const sound1 = new Audio(`${baseUrl}/assets/audio/sound1.mp3`);
    const sound2 = new Audio(`${baseUrl}/assets/audio/sound2.mp3`);
    
    // Store references
    audioRefs.current = { sound1, sound2 };

    // Add event listeners for debugging
    sound1.addEventListener('error', (e) => {
      console.error('Sound1 error:', e.target.error);
      console.error('Sound1 URL:', sound1.src);
    });
    sound2.addEventListener('error', (e) => {
      console.error('Sound2 error:', e.target.error);
      console.error('Sound2 URL:', sound2.src);
    });

    // Preload audio
    const preloadAudio = async () => {
      try {
        // Set preload attribute
        sound1.preload = 'auto';
        sound2.preload = 'auto';
        
        // Load audio files
        await Promise.all([
          new Promise((resolve, reject) => {
            sound1.addEventListener('canplaythrough', resolve, { once: true });
            sound1.addEventListener('error', reject, { once: true });
            sound1.load();
          }),
          new Promise((resolve, reject) => {
            sound2.addEventListener('canplaythrough', resolve, { once: true });
            sound2.addEventListener('error', reject, { once: true });
            sound2.load();
          })
        ]);
        console.log('Audio files loaded successfully');
      } catch (error) {
        console.error('Error preloading audio:', error);
      }
    };
    preloadAudio();

    return () => {
      // Cleanup audio on unmount
      const { sound1, sound2 } = audioRefs.current;
      if (sound1) {
        sound1.pause();
        sound1.currentTime = 0;
      }
      if (sound2) {
        sound2.pause();
        sound2.currentTime = 0;
      }
    };
  }, []);

  const startSequence = async () => {
    setStarted(true);
    try {
      const { sound1, sound2 } = audioRefs.current;
      
      // Play sound1 and wait for it to end
      if (sound1) {
        console.log('Playing sound1');
        await new Promise((resolve, reject) => {
          sound1.onended = () => {
            console.log('Sound1 ended');
            resolve();
          };
          sound1.onerror = (e) => {
            console.error('Sound1 playback error:', e.target.error);
            reject(e.target.error);
          };
          const playPromise = sound1.play();
          if (playPromise !== undefined) {
            playPromise.catch(error => {
              console.error('Sound1 play error:', error);
              reject(error);
            });
          }
        });
      }

      // Show message and play sound2 simultaneously
      setShowMessage(true);
      if (sound2) {
        console.log('Playing sound2');
        await new Promise((resolve, reject) => {
          sound2.onended = () => {
            console.log('Sound2 ended');
            resolve();
          };
          sound2.onerror = (e) => {
            console.error('Sound2 playback error:', e.target.error);
            reject(e.target.error);
          };
          const playPromise = sound2.play();
          if (playPromise !== undefined) {
            playPromise.catch(error => {
              console.error('Sound2 play error:', error);
              reject(error);
            });
          }
        });
      }

      // Wait for sound2 to finish before starting fade out
      await new Promise(resolve => setTimeout(resolve, 1000));
      setFadeOut(true);
      await new Promise(resolve => setTimeout(resolve, 1000));
      onComplete();
    } catch (error) {
      console.error('Error in sequence:', error);
      // Continue with the sequence even if audio fails
      setShowMessage(true);
      setFadeOut(true);
      setTimeout(() => onComplete(), 2000);
    }
  };

  const skipIntro = () => {
    setFadeOut(true);
    setTimeout(() => onComplete(), 1000);
  };

  return (
    <div className={`fixed inset-0 bg-gradient-to-b from-gray-900 to-black z-50 flex items-center justify-center transition-opacity duration-1000 ${fadeOut ? 'opacity-0' : 'opacity-100'}`}>
      {!started ? (
        <div className="text-center space-y-6 animate-fade-in">
          <button
            className="bg-red-600 text-white px-12 py-6 rounded-xl text-2xl shadow-lg hover:bg-red-700 transition-all duration-300 transform hover:scale-105 animate-pulse"
            onClick={startSequence}
          >
            เริ่มต้น
          </button>
          <button
            className="block mx-auto text-gray-400 hover:text-white transition-colors duration-300 animate-fade-in-delay"
            onClick={skipIntro}
          >
            ข้ามบทนำ
          </button>
        </div>
      ) : (
        <div className={`text-center transition-all duration-1000 ${showMessage ? 'opacity-100 scale-100' : 'opacity-0 scale-95'}`}>
          <h2 className="text-5xl font-bold text-white mb-6 animate-fade-in">
            ชีวิตสั้นกว่าที่คิด...
          </h2>
          <p className="text-3xl text-gray-300 animate-fade-in-delay">
            วางแผนวันสุดท้ายไว้ก่อนดีไหม?
          </p>
        </div>
      )}
    </div>
  );
}

export default IntroOverlay; 